import {
  ScrollSequence as Engine,
  parseManifest,
  posterUrl,
  type SequenceManifest,
} from "@scrollframe/core";
import { useEffect, useMemo, useRef, type CSSProperties, type ReactNode } from "react";

export { PROGRESS_CSS_VAR, type SequenceManifest } from "@scrollframe/core";

export interface ScrollSequenceProps {
  /** Contents of the `manifest.json` generated by the CLI (import it statically for SSR). */
  manifest: SequenceManifest | unknown;
  /** Describes the scene. It is the alt text of the poster, the only image search engines index. */
  alt: string;
  /** Total scroll distance of the section. Longer = slower playback. Default "300vh". */
  scrollLength?: string;
  /** Overrides `manifest.baseUrl` (e.g. a CDN). */
  baseUrl?: string;
  /** Above-the-fold hero: poster loads eagerly with high priority (good LCP). Default true. */
  priority?: boolean;
  /** Overlay content (headings, copy, CTAs). Rendered as real HTML on top of the sequence. */
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
  overlayClassName?: string;
  onProgress?: (progress: number, frameIndex: number) => void;
}

const fill: CSSProperties = {
  position: "absolute",
  inset: 0,
  width: "100%",
  height: "100%",
  objectFit: "cover",
};

export function ScrollSequence({
  manifest: rawManifest,
  alt,
  scrollLength = "300vh",
  baseUrl,
  priority = true,
  children,
  className,
  style,
  overlayClassName,
  onProgress,
}: ScrollSequenceProps) {
  const manifest = useMemo(() => parseManifest(rawManifest), [rawManifest]);
  const containerRef = useRef<HTMLElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const onProgressRef = useRef(onProgress);
  onProgressRef.current = onProgress;

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const engine = new Engine({
      container,
      canvas,
      manifest,
      baseUrl,
      onProgress: (progress, index) => onProgressRef.current?.(progress, index),
    }).start();
    return () => engine.destroy();
  }, [manifest, baseUrl]);

  const largest = manifest.sets[manifest.sets.length - 1]!;

  return (
    <section ref={containerRef} className={className} style={{ position: "relative", height: scrollLength, ...style }}>
      <div style={{ position: "sticky", top: 0, height: "100svh", overflow: "hidden" }}>
        <picture>
          {manifest.sets
            .filter((set) => set.maxViewportWidth !== null)
            .map((set) => (
              <source
                key={set.name}
                media={`(max-width: ${set.maxViewportWidth}px)`}
                srcSet={posterUrl(manifest, set, baseUrl)}
                width={set.width}
                height={set.height}
                type="image/webp"
              />
            ))}
          <img
            src={posterUrl(manifest, largest, baseUrl)}
            alt={alt}
            width={largest.width}
            height={largest.height}
            loading={priority ? "eager" : "lazy"}
            fetchPriority={priority ? "high" : "auto"}
            decoding="async"
            style={fill}
          />
        </picture>
        <canvas ref={canvasRef} aria-hidden="true" style={{ ...fill, pointerEvents: "none" }} />
        <div className={overlayClassName} style={{ position: "absolute", inset: 0 }}>
          {children}
        </div>
      </div>
    </section>
  );
}
